<template><main class="admin-content">
<div class="mb-6 flex flex-wrap items-end justify-between gap-3"><div><p class="text-xs font-black uppercase tracking-wider text-indigo-600">Accounting</p><h1 class="text-3xl font-black">Bank Reconciliation</h1><p class="text-slate-500">Import statement transactions, match them to the ledger and reconcile the statement balance.</p></div><NuxtLink to="/admin/accounting" class="secondary">← Accounting</NuxtLink></div>
<div v-if="err" class="mb-4 rounded-xl bg-red-50 p-4 text-red-700">{{err}}</div><div v-if="notice" class="mb-4 rounded-xl bg-emerald-50 p-4 text-emerald-700">{{notice}}</div>
<section class="panel p-5"><div class="flex flex-wrap items-end gap-3"><div class="min-w-64 flex-1"><label class="label">Bank account</label><select v-model.number="bankId" class="input" @change="loadTransactions"><option :value="0">Select bank account</option><option v-for="a in banks" :key="a.id" :value="a.id">{{a.name}} · {{a.accounting_accounts?.code}} {{a.accounting_accounts?.name}}</option></select></div><button class="primary" @click="showBank=true">+ Bank Account</button><button class="secondary" :disabled="!bankId" @click="fileInput?.click()">Import CSV</button><input ref="fileInput" class="hidden" type="file" accept=".csv,text/csv" @change="importCsv"></div></section>
<div v-if="bankId" class="mt-5 grid gap-4 md:grid-cols-4"><div class="panel p-5"><small>Statement transactions</small><div class="text-3xl font-black">{{tx.length}}</div></div><div class="panel p-5"><small>Unmatched</small><div class="text-3xl font-black text-amber-600">{{unmatched}}</div></div><div class="panel p-5"><small>Matched</small><div class="text-3xl font-black text-blue-600">{{matched}}</div></div><div class="panel p-5"><small>Reconciled</small><div class="text-3xl font-black text-emerald-600">{{reconciled}}</div></div></div>
<section v-if="bankId" class="panel mt-5 p-5"><div class="flex flex-wrap items-center justify-between gap-3"><div><h2 class="text-xl font-black">Statement Transactions</h2><p class="text-sm text-slate-500">CSV columns: Date, Description, Reference, Amount. Deposits are positive; withdrawals are negative.</p></div><select v-model="filter" class="input max-w-44"><option value="all">All</option><option value="unmatched">Unmatched</option><option value="matched">Matched</option><option value="reconciled">Reconciled</option></select></div>
<div class="mt-4 overflow-x-auto"><table class="w-full text-sm"><thead><tr class="border-b text-left"><th class="p-2">Date</th><th>Description</th><th>Reference</th><th class="text-right">Amount</th><th>Status</th><th class="text-right">Action</th></tr></thead><tbody><tr v-for="t in filtered" :key="t.id" class="border-b"><td class="p-2 whitespace-nowrap">{{t.transaction_date}}</td><td>{{t.description}}</td><td>{{t.reference||'—'}}</td><td class="text-right font-black" :class="t.amount>0?'text-emerald-700':'text-red-700'">{{money(t.amount)}}</td><td><span class="badge" :class="'s-'+t.status">{{t.status}}</span></td><td class="py-2 text-right"><button v-if="t.status==='unmatched'" class="primary small" @click="openMatch(t)">Match</button><span v-else class="text-xs text-slate-500">{{t.match_type?.replaceAll('_',' ')}}</span></td></tr><tr v-if="!filtered.length"><td colspan="6" class="p-8 text-center text-slate-500">No transactions.</td></tr></tbody></table></div></section>
<section v-if="bankId" class="panel mt-5 p-5"><h2 class="text-xl font-black">Reconcile Statement</h2><p class="text-sm text-slate-500">All transactions up to the statement date must be matched and the calculated balance must equal the statement closing balance.</p><div class="mt-4 grid gap-3 md:grid-cols-3"><div><label class="label">Statement date</label><input v-model="statement.date" type="date" class="input"></div><div><label class="label">Closing balance</label><input v-model.number="statement.balance" type="number" step="0.01" class="input"></div><div class="flex items-end"><button class="primary w-full" @click="reconcile">Reconcile</button></div></div><div v-if="history.length" class="mt-5"><h3 class="font-black">History</h3><div v-for="h in history" :key="h.id" class="mt-2 flex justify-between rounded-lg bg-slate-50 p-3 text-sm"><span>{{h.statement_date}}</span><b>{{money(h.statement_balance)}}</b></div></div></section>
<div v-if="showBank" class="modal" @click.self="showBank=false"><div class="modal-card"><h2 class="text-xl font-black">Add Bank Account</h2><label class="label">Name</label><input v-model="bank.name" class="input" placeholder="Business Transaction Account"><div class="grid grid-cols-2 gap-3"><div><label class="label">BSB</label><input v-model="bank.bsb" class="input"></div><div><label class="label">Account number</label><input v-model="bank.account_number" class="input"></div></div><label class="label">Ledger bank account</label><select v-model.number="bank.accounting_account_id" class="input"><option :value="0">Select account</option><option v-for="a in ledgerBanks" :key="a.id" :value="a.id">{{a.code}} · {{a.name}}</option></select><label class="label">Opening balance</label><input v-model.number="bank.opening_balance" type="number" step="0.01" class="input"><div class="mt-5 flex justify-end gap-2"><button class="secondary" @click="showBank=false">Cancel</button><button class="primary" @click="saveBank">Save</button></div></div></div>
<div v-if="matchTx" class="modal" @click.self="matchTx=null"><div class="modal-card max-w-2xl"><h2 class="text-xl font-black">Match Bank Transaction</h2><div class="my-4 rounded-xl bg-slate-50 p-4"><b>{{matchTx.description}}</b><div class="mt-1 flex justify-between"><span>{{matchTx.transaction_date}}</span><b>{{money(matchTx.amount)}}</b></div></div><h3 class="font-black">Suggested accounting payments</h3><button v-for="c in candidates" :key="c.type+'-'+c.id" class="mt-2 flex w-full justify-between rounded-xl border p-3 text-left hover:bg-slate-50" @click="matchCandidate(c)"><span>{{c.label}}</span><b>{{money(c.amount)}}</b></button><p v-if="!candidates.length" class="my-3 text-sm text-slate-500">No exact payment match found within 7 days.</p><label class="label">Or allocate manually to ledger account</label><select v-model.number="manualAccount" class="input"><option :value="0">Select account</option><option v-for="a in manualAccounts" :key="a.id" :value="a.id">{{a.code}} · {{a.name}}</option></select><div class="mt-5 flex justify-end gap-2"><button class="secondary" @click="matchTx=null">Cancel</button><button class="primary" :disabled="!manualAccount" @click="manualMatch">Create & Match Journal</button></div></div></div>
</main></template>
<script setup lang="ts">
definePageMeta({layout:'admin',middleware:['admin']});const {adminFetch,isSuperAdmin}=useAdminFetch();const banks=ref<any[]>([]),accounts=ref<any[]>([]),tx=ref<any[]>([]),history=ref<any[]>([]),bankId=ref(0),filter=ref('all'),err=ref(''),notice=ref(''),showBank=ref(false),matchTx=ref<any>(null),candidates=ref<any[]>([]),manualAccount=ref(0),fileInput=ref<HTMLInputElement|null>(null);const bank=reactive({name:'',bsb:'',account_number:'',accounting_account_id:0,opening_balance:0}),statement=reactive({date:new Date().toISOString().slice(0,10),balance:0});const money=(v:any)=>new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD'}).format(Number(v||0));const filtered=computed(()=>filter.value==='all'?tx.value:tx.value.filter(x=>x.status===filter.value));const unmatched=computed(()=>tx.value.filter(x=>x.status==='unmatched').length),matched=computed(()=>tx.value.filter(x=>x.status==='matched').length),reconciled=computed(()=>tx.value.filter(x=>x.status==='reconciled').length);const ledgerBanks=computed(()=>accounts.value.filter(a=>a.account_type==='asset'));const selectedBank=computed(()=>banks.value.find(x=>x.id===bankId.value));const manualAccounts=computed(()=>accounts.value.filter(a=>a.active&&a.id!==selectedBank.value?.accounting_account_id));
async function init(){if(!isSuperAdmin.value)return navigateTo('/admin');try{[banks.value,accounts.value]=await Promise.all([adminFetch('/api/admin/accounting/bank/accounts'),adminFetch('/api/admin/accounting/accounts')]);if(banks.value.length){bankId.value=banks.value[0].id;await loadTransactions()}}catch(e:any){err.value=e?.data?.statusMessage||e.message}}
async function loadTransactions(){if(!bankId.value)return;try{[tx.value,history.value]=await Promise.all([adminFetch(`/api/admin/accounting/bank/transactions?bank_account_id=${bankId.value}`),adminFetch(`/api/admin/accounting/bank/reconciliations?bank_account_id=${bankId.value}`)])}catch(e:any){err.value=e?.data?.statusMessage||e.message}}
async function saveBank(){try{await adminFetch('/api/admin/accounting/bank/accounts',{method:'POST',body:bank});showBank.value=false;banks.value=await adminFetch('/api/admin/accounting/bank/accounts');bankId.value=banks.value.at(-1)?.id||bankId.value;await loadTransactions()}catch(e:any){err.value=e?.data?.statusMessage||e.message}}
function parseCsv(text:string){const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(Boolean);if(lines.length<2)return[];const split=(line:string)=>{const out:string[]=[];let cur='',q=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){if(q&&line[i+1]==='"'){cur+='"';i++}else q=!q}else if(c===','&&!q){out.push(cur.trim());cur=''}else cur+=c}out.push(cur.trim());return out};const h=split(lines[0]).map(x=>x.toLowerCase().replace(/[^a-z]/g,''));const idx=(...names:string[])=>h.findIndex(x=>names.includes(x));const di=idx('date','transactiondate'),xi=idx('description','details','narrative'),ri=idx('reference','ref'),ai=idx('amount'),debi=idx('debit','withdrawal'),cri=idx('credit','deposit');return lines.slice(1).map(line=>{const c=split(line);let raw=ai>=0?c[ai]:'';let amount=Number(String(raw||'').replace(/[$,]/g,''));if(ai<0)amount=Number(String(c[cri]||'').replace(/[$,]/g,''))-Number(String(c[debi]||'').replace(/[$,]/g,''));let d=c[di]||'';if(/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(d)){const [dd,mm,yy]=d.split('/');d=`${yy}-${mm.padStart(2,'0')}-${dd.padStart(2,'0')}`}return {transaction_date:d,description:c[xi]||'',reference:ri>=0?c[ri]:'',amount}}).filter(x=>x.transaction_date&&Number.isFinite(x.amount)&&x.amount!==0)}
async function importCsv(e:any){const f=e.target.files?.[0];if(!f)return;try{const rows=parseCsv(await f.text());const r:any=await adminFetch('/api/admin/accounting/bank/import',{method:'POST',body:{bank_account_id:bankId.value,rows}});notice.value=`Imported ${r.imported} transaction(s); ${r.skipped} duplicate/invalid row(s) skipped.`;await loadTransactions()}catch(x:any){err.value=x?.data?.statusMessage||x.message}finally{e.target.value=''}}
async function openMatch(t:any){matchTx.value=t;manualAccount.value=0;candidates.value=await adminFetch(`/api/admin/accounting/bank/candidates?amount=${t.amount}&date=${t.transaction_date}`)}async function matchCandidate(c:any){await adminFetch('/api/admin/accounting/bank/match',{method:'POST',body:{transaction_id:matchTx.value.id,match_type:c.type,match_id:c.id}});matchTx.value=null;await loadTransactions()}async function manualMatch(){await adminFetch('/api/admin/accounting/bank/manual',{method:'POST',body:{transaction_id:matchTx.value.id,account_id:manualAccount.value}});matchTx.value=null;await loadTransactions()}async function reconcile(){try{await adminFetch('/api/admin/accounting/bank/reconcile',{method:'POST',body:{bank_account_id:bankId.value,statement_date:statement.date,statement_balance:statement.balance}});notice.value='Bank statement reconciled successfully.';await loadTransactions()}catch(e:any){err.value=e?.data?.statusMessage||e.message}}onMounted(init)
</script>
<style scoped>.panel{@apply rounded-xl border border-slate-200 bg-white shadow-sm}.label{@apply mt-3 mb-1 block text-xs font-black uppercase tracking-wide text-slate-600}.input{@apply w-full rounded-lg border border-slate-300 bg-white px-3 py-2}.primary{@apply rounded-lg bg-blue-600 px-4 py-2 text-sm font-black text-white hover:bg-blue-700 disabled:opacity-50}.secondary{@apply rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-bold}.small{@apply px-3 py-1.5}.badge{@apply rounded-full px-2 py-1 text-xs font-black capitalize}.s-unmatched{@apply bg-amber-100 text-amber-800}.s-matched{@apply bg-blue-100 text-blue-800}.s-reconciled{@apply bg-emerald-100 text-emerald-800}.modal{@apply fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4}.modal-card{@apply w-full max-w-lg rounded-2xl bg-white p-6 shadow-2xl}</style>
